onClick:
{{
  insertImportPotwierdzenia.run()
    .then(async wynik => {
      if (!wynik.length) {
        showAlert(
          "Nie zapisano danych. Sprawdź ważność sesji.",
          "error"
        );
        return;
      }

      showAlert(
        "Zaimportowano " + wynik.length + " rekordów.",
        "success"
      );

      await removeValue("importPotwierdzenia");
      await resetWidget("FilePickerImport", true);
      closeModal("ModalImportPotwierdzenia");

      try {
        await getPotwierdzenia.run();
      } catch (error) {
        showAlert(
          "Import zakończony, ale nie udało się odświeżyć tabeli.",
          "warning"
        );
      }
    })
    .catch(error => {
      showAlert(
        "Błąd importu: " + error.message,
        "error"
      );
    })
}}
